import { useMemo } from 'react';

/**
 * Pixel art character rendered as an SVG grid.
 * Each character is a 12x16 pixel grid with legs, arms, body, and a funny head.
 * Colors are driven by a palette. Animations via CSS transforms on the parent.
 */

const PX = 1; // Each pixel = 1 SVG unit. Scale via width/height on the <svg>.

type Palette = {
  skin: string;
  body: string;
  bodyDark: string;
  shoes: string;
  eyes: string;
  mouth: string;
  hat: string;
  accent: string;
};

// _ = transparent, S = skin, B = body, D = bodyDark, H = hat, E = eyes, M = mouth, A = accent, X = shoes
type PixelKey = '_' | 'S' | 'B' | 'D' | 'H' | 'E' | 'M' | 'A' | 'X';

function keyToColor(key: PixelKey, p: Palette): string | null {
  switch (key) {
    case 'S': return p.skin;
    case 'B': return p.body;
    case 'D': return p.bodyDark;
    case 'H': return p.hat;
    case 'E': return p.eyes;
    case 'M': return p.mouth;
    case 'A': return p.accent;
    case 'X': return p.shoes;
    default: return null;
  }
}

