export type CharacterPose = 'idle' | 'jump' | 'walk' | 'dead';

const POSE_MAP: Record<CharacterPose, PixelKey[][]> = {
  idle: CHAR_IDLE,
  jump: CHAR_JUMP,
  walk: CHAR_WALK1,
  dead: CHAR_DEAD,
};

interface PixelCharacterProps {
  paletteIndex: number;
  pose?: CharacterPose;
  size?: number;
  flipX?: boolean;
  style?: React.CSSProperties;
  className?: string;
}

export function PixelCharacter({
  paletteIndex,
  pose = 'idle',
  size = 48,
  flipX = false,
  style,
  className,
}: PixelCharacterProps) {
  const palette = PALETTES[paletteIndex % PALETTES.length];
  const grid = POSE_MAP[pose];

  const rows = grid.length;
  const cols = grid[0].length;

  const pixels = useMemo(() => {
    const result: { x: number; y: number; color: string }[] = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const color = keyToColor(grid[r][c], palette);
        if (color) result.push({ x: c, y: r, color });
      }
    }
    return result;
  }, [grid, palette, rows, cols]);

  return (
    <svg
      width={size}
      height={size * (rows / cols)}
      viewBox={`0 0 ${cols} ${rows}`}
      style={{
        imageRendering: 'pixelated',
        transform: flipX ? 'scaleX(-1)' : undefined,
        ...style,
      }}
      className={className}
    >
      {pixels.map((p, i) => (
        <rect key={i} x={p.x} y={p.y} width={PX} height={PX} fill={p.color} />
      ))}
    </svg>
  );
}
