const CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

export function generateRoomCode(): string {
  return Array.from({ length: 6 }, () =>
    CHARS[Math.floor(Math.random() * CHARS.length)],
  ).join('');
}

export function channelName(gameId: string, code: string): string {
  return `${gameId}-${code.toUpperCase()}`;
}

// ─── Themed room names ──────────────────────────────────────────────────────

const ADJECTIVES = [
  'turbo', 'mega', 'super', 'epic', 'cosmic', 'blazing', 'wild', 'hyper',
  'magic', 'thunder', 'golden', 'silver', 'crystal', 'phantom', 'stellar',
  'neon', 'atomic', 'mystic', 'shadow', 'lucky',
];

const GAME_NOUNS: Record<string, string[]> = {
  tictactoe: ['grid', 'cross', 'circle', 'duel', 'board', 'square'],
  spotit: ['eyes', 'flash', 'cards', 'match', 'reflex', 'hunt'],
  memory: ['brain', 'flip', 'pairs', 'cards', 'mind', 'vault'],
  stopgame: ['words', 'rush', 'sprint', 'blitz', 'clash', 'race'],
};

const FALLBACK_NOUNS = ['arena', 'zone', 'battle', 'quest', 'clash', 'showdown'];

function pick<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

export function generateRoomName(gameId: string, playerName: string): string {
  const adj = pick(ADJECTIVES);
  const nouns = GAME_NOUNS[gameId] ?? FALLBACK_NOUNS;
  const noun = pick(nouns);
  const short = playerName.slice(0, 8).trim();
  return `${short}'s ${adj} ${noun}`;
}
