import { useState, useEffect, useRef, useCallback } from 'react';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { createBroadcastChannel, removeChannel } from './realtime';

const ROOM_TTL_MS = 24 * 60 * 60 * 1000; // 1 day
const HEARTBEAT_MS = 20_000; // 20s
const STALE_MS = 45_000; // remove if no heartbeat in 45s

export interface RoomListing {
  code: string;
  roomName: string;
  gameId: string;
  hostName: string;
  playerCount: number;
  createdAt: number;
  lastSeen: number;
}

interface UseRoomBrowserOptions {
  gameId: string;
  enabled: boolean;
}

interface UseRoomBrowserReturn {
  rooms: RoomListing[];
  /** Call when you create a room — starts broadcasting presence */
  publishRoom: (info: { code: string; roomName: string; hostName: string; playerCount: number }) => void;
  /** Update player count while room is active */
  updatePlayerCount: (count: number) => void;
  /** Stop broadcasting (room closed) */
  unpublishRoom: () => void;
}

export function useRoomBrowser({ gameId, enabled }: UseRoomBrowserOptions): UseRoomBrowserReturn {
  const [rooms, setRooms] = useState<RoomListing[]>([]);
  const channelRef = useRef<RealtimeChannel | null>(null);
  const heartbeatRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const publishedRef = useRef<RoomListing | null>(null);
  const roomsMapRef = useRef<Map<string, RoomListing>>(new Map());

  // Subscribe to the lobby channel to receive room listings
  useEffect(() => {
    if (!enabled) return;

    const ch = createBroadcastChannel(`lobby-${gameId}`);
    channelRef.current = ch;

    ch.on('broadcast', { event: 'room-heartbeat' }, ({ payload }) => {
      const listing = payload as RoomListing;
      const now = Date.now();
      // Ignore rooms older than TTL
      if (now - listing.createdAt > ROOM_TTL_MS) return;
      listing.lastSeen = now;
      roomsMapRef.current.set(listing.code, listing);
      setRooms(Array.from(roomsMapRef.current.values()));
    });

    ch.on('broadcast', { event: 'room-closed' }, ({ payload }) => {
      const { code } = payload as { code: string };
      roomsMapRef.current.delete(code);
      setRooms(Array.from(roomsMapRef.current.values()));
    });

    ch.subscribe();

    // Periodically prune stale rooms
    const pruneInterval = setInterval(() => {
      const now = Date.now();
      let changed = false;
      for (const [code, room] of roomsMapRef.current) {
        if (now - room.lastSeen > STALE_MS || now - room.createdAt > ROOM_TTL_MS) {
          roomsMapRef.current.delete(code);
          changed = true;
        }
      }
      if (changed) setRooms(Array.from(roomsMapRef.current.values()));
    }, 10_000);

    // Request existing rooms (hosts will re-heartbeat)
    setTimeout(() => {
      ch.send({ type: 'broadcast', event: 'room-request', payload: {} });
    }, 500);

    return () => {
      clearInterval(pruneInterval);
      if (channelRef.current) {
        removeChannel(channelRef.current);
        channelRef.current = null;
      }
      roomsMapRef.current.clear();
    };
  }, [gameId, enabled]);

  // Listen for room-request from new browsers — re-heartbeat if we're hosting
  useEffect(() => {
    if (!enabled || !channelRef.current) return;
    const ch = channelRef.current;
    const handler = () => {
      if (publishedRef.current) {
        ch.send({
          type: 'broadcast',
          event: 'room-heartbeat',
          payload: { ...publishedRef.current, lastSeen: Date.now() },
        });
      }
    };
    ch.on('broadcast', { event: 'room-request' }, handler);
    // No way to unsubscribe individual handlers in Supabase, cleanup is handled by channel removal
  }, [enabled]);

  const publishRoom = useCallback((info: { code: string; roomName: string; hostName: string; playerCount: number }) => {
    const listing: RoomListing = {
      ...info,
      gameId,
      createdAt: Date.now(),
      lastSeen: Date.now(),
    };
    publishedRef.current = listing;

    // Immediate broadcast
    channelRef.current?.send({
      type: 'broadcast',
      event: 'room-heartbeat',
      payload: listing,
    });

    // Heartbeat every 20s
    if (heartbeatRef.current) clearInterval(heartbeatRef.current);
    heartbeatRef.current = setInterval(() => {
      if (publishedRef.current && channelRef.current) {
        publishedRef.current.lastSeen = Date.now();
        channelRef.current.send({
          type: 'broadcast',
          event: 'room-heartbeat',
          payload: publishedRef.current,
        });
      }
    }, HEARTBEAT_MS);
  }, [gameId]);

  const updatePlayerCount = useCallback((count: number) => {
    if (publishedRef.current) {
      publishedRef.current.playerCount = count;
    }
  }, []);

  const unpublishRoom = useCallback(() => {
    if (heartbeatRef.current) {
      clearInterval(heartbeatRef.current);
      heartbeatRef.current = null;
    }
    if (publishedRef.current && channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'room-closed',
        payload: { code: publishedRef.current.code },
      });
    }
    publishedRef.current = null;
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (heartbeatRef.current) clearInterval(heartbeatRef.current);
      if (publishedRef.current && channelRef.current) {
        channelRef.current.send({
          type: 'broadcast',
          event: 'room-closed',
          payload: { code: publishedRef.current.code },
        });
      }
      publishedRef.current = null;
    };
  }, []);

  return { rooms, publishRoom, updatePlayerCount, unpublishRoom };
}
